                let (var_form, br) = cp(binding);
                let (count_form, result_rest) = cp(br);
                bliss_rt::rooted!(var_form = var_form);
                bliss_rt::rooted!(count_form = count_form);
                bliss_rt::rooted!(result_rest = result_rest);
                bliss_rt::rooted!(body = body);
